SAMPLE_HTML = """<!doctype html><html lang="zh-CN"><head><meta charset="UTF-8"><style>*{box-sizing:border-box}body{margin:0;padding:48px;background:#f4f6f9;color:#18253b;font-family:system-ui,sans-serif}header{background:#18253b;color:white;border-radius:20px;padding:30px;margin-bottom:25px}h1{margin:0 0 8px}p{opacity:.7}section{background:white;border-radius:16px;padding:25px;margin:20px 0}form{display:flex;gap:12px}input{flex:1;padding:14px;border:1px solid #dce1e7;border-radius:9px;font:inherit}button{padding:12px 18px;border:0;border-radius:8px;background:#d9f27b;color:#18253b;cursor:pointer;font:inherit}nav{display:flex;gap:10px;margin-bottom:20px}nav button{background:#edf0f5}nav button.active{background:#18253b;color:white}.task{display:flex;align-items:center;gap:12px;padding:18px 0;border-bottom:1px solid #eee}.task span{flex:1}.done{text-decoration:line-through;color:#888}.task input{flex:0}.muted{color:#8993a0}footer{font-size:12px;color:#8993a0}progress{width:100%;accent-color:#18253b}</style></head><body><header><h1>任务工作台</h1><p>把想法变成行动，专注每一次交付。</p><div id="stat"></div></header><section><form id="form"><input id="text" placeholder="下一件想完成的事…" aria-label="任务名称" maxlength="120" required><button>＋ 添加任务</button></form></section><section><nav><button data-filter="all" class="active">全部任务</button><button data-filter="todo">进行中</button><button data-filter="done">已完成</button></nav><div id="list"></div><progress id="progress" max="100"></progress></section><footer>演示应用 · 数据保存在当前浏览器 · 使用同一项目继续修改</footer><script>let tasks=JSON.parse(localStorage.getItem('forge-tasks')||'[{"id":1,"text":"梳理产品需求","done":true},{"id":2,"text":"完成第一个可运行版本","done":false},{"id":3,"text":"邀请用户体验并收集反馈","done":false}]');let filter='all';function render(){localStorage.setItem('forge-tasks',JSON.stringify(tasks));document.querySelector('#list').replaceChildren();tasks.filter(t=>filter==='all'||(filter==='done'?t.done:!t.done)).forEach(t=>{const row=document.createElement('div');row.className='task';const check=document.createElement('input');check.type='checkbox';check.checked=t.done;check.setAttribute('aria-label','完成 '+t.text);check.onchange=()=>{t.done=check.checked;render()};const text=document.createElement('span');text.textContent=t.text;text.className=t.done?'done':'';const del=document.createElement('button');del.textContent='删除';del.onclick=()=>{tasks=tasks.filter(x=>x.id!==t.id);render()};row.append(check,text,del);document.querySelector('#list').append(row)});const count=tasks.filter(t=>t.done).length;document.querySelector('#stat').textContent=count+' / '+tasks.length+' 项任务已完成';document.querySelector('#progress').value=tasks.length?count/tasks.length*100:0;}document.querySelector('#form').onsubmit=e=>{e.preventDefault();const input=document.querySelector('#text');if(!input.value.trim())return;tasks.push({id:Date.now(),text:input.value.trim(),done:false});input.value='';render()};document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('nav button').forEach(x=>x.classList.toggle('active',x===b));render()});render();</script></body></html>"""
